import{z as p,x as A,o as E,c as d,q as o,j as s,D as e,d as n,s as i,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"冯·诺依曼–Morgenstern 期望效用","description":"","frontmatter":{"title":"冯·诺依曼–Morgenstern 期望效用","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/expected-utility.md","filePath":"econ/expected-utility.md","lastUpdated":1791413859000}'),u={name:"econ/expected-utility.md"};function B(m,a,h,c,C,D){const r=A("Mermaid");return E(),d("div",null,[a[2]||(a[2]=o('<h1 id="冯·诺依曼–morgenstern-期望效用" tabindex="-1">冯·诺依曼–Morgenstern 期望效用 <a class="header-anchor" href="#冯·诺依曼–morgenstern-期望效用" aria-label="Permalink to &quot;冯·诺依曼–Morgenstern 期望效用&quot;">​</a></h1><div class="epigraph"><p>若偏好满足完备、传递、连续性与独立性，则存在效用，使彩票的排序等于结果效用的概率加权平均。</p><footer>—— 据 von Neumann and Morgenstern, Theory of Games and Economic Behavior, 1944 整理</footer></div><p><a href="/econ/two-period-micro">上一课</a>（两期消费）。在确定消费束上把偏好与需求闭环。本课不重讲 Afriat 或斯勒茨基，也不把确定的 \\(u(x)\\) 直接拿来对随机结果取期望。缺口是：备选集从 \\(X\\) 换成了 \\(X\\) 上的彩票 \\(\\Delta(X)\\)。理性偏好仍必要，但不够——没有对复合彩票的结构，期望算子没有公理地位。本课打开「不确定下的选择」课序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>确定束上的连续效用是序数的：单调变换保持表示。若结果是随机的，决策者比较的是分布，不是某个已实现的 \\(x\\)。若只把「分布的某个数字」随意指定成效用，后课的风险厌恶、随机占优都没有共同刻度。缺口是给出一套公理，使偏好能写成</p> \\[U(F)=\\int u(x)\\,dF(x), \\]<p>其中 \\(u\\) 是结果上的伯努利函数，\\(U\\) 是彩票上的 vNM 效用。关键新公理是独立性：对一切彩票 \\(F,G,H\\) 与 \\(\\alpha\\in(0,1)\\)，</p> \\[F\\succsim G \\iff \\alpha F+(1-\\alpha)H\\succsim \\alpha G+(1-\\alpha)H. \\]<p>混入同一 \\(H\\) 不改变排序。连续性（阿基米德）保证概率权重可以当成实数来用。本课只钉这一表示；阿莱对独立性的挑战是下一课。</p><p><span class="marginnote">独立性说白了就是「掺水不改口味」：在两个候选里兑入同一份第三种彩票（按相同比例混合），原来更好的那个仍然更好。就像在两杯好酒与坏酒里都兑同样多的水，好坏排序不变。这条公理让概率真正退化为权重，是期望形式唯一需要的关键肌肉。</span></p><h3 id="伯努利函数不是确定消费里那个" tabindex="-1">伯努利函数不是确定消费里那个 \\(u\\) <a class="header-anchor" href="#伯努利函数不是确定消费里那个" aria-label="Permalink to &quot;伯努利函数不是确定消费里那个 $u$&quot;">​</a></h3><p>确定课序恢复的 \\(u\\) 只排确定束。vNM 的 \\(u\\) 排的是退化彩票，并且在仿射变换 \\(au+b\\)（\\(a\\gt 0\\)）下唯一。基数性来自独立性，不是来自「效用可测」。把 Cobb–Douglas 的序数 \\(u\\) 直接塞进期望，是偷运了跨状态可加，必须另证。</p><p><span class="marginnote">复合彩票的简化：两阶段随机先还原成一阶段分布，再比较。独立性保证这个简化与偏好一致。后课若放弃独立性，复合彩票的折开方式本身会改变选择。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象是有限支撑彩票，或简单测度。公理：\\(\\Delta(X)\\) 上理性、连续、独立。结论：存在 \\(u:X\\to\\mathbb{R}\\)，在仿射变换下唯一，使 \\(F\\succsim G\\) 当且仅当 \\(\\mathbb{E}_F u\\ge\\mathbb{E}_G u\\)。证明的构造是：把最好与最差当锚，用无差异概率当效用——这正是「概率当权重」的操作定义。</p><p><span class="marginnote">这个构造像调音校准：把「最好的结果」定为 1、「最差的结果」定为 0，然后拿一个中间结果（比如一辆车）来问——多大的概率 \\(p\\) 抽中最好、其余抽中最差，才让你觉得与直接得到这辆车无差异？若答案是 \\(p=0.8\\)，这辆车的效用就是 0.8。效用数值由此从偏好本身读出来，而不是拍脑袋给的分数。</span></p><p>期望是线性的，所以 \\(U\\) 在彩票混合上线性。这比确定情形强得多：确定 \\(u\\) 的单调变换这里一般不合法，只剩仿射。后课 Arrow–Pratt 用 \\(u\\) 的凹性说话，靠的就是这点基数性。</p>',17)),(E(),s(l,null,{default:e(()=>[i(r,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E5%BD%A9%E7%A5%A8%20%CE%94(X)%22%5D%20--%3E%20AX%5B%22%E7%90%86%E6%80%A7%20%2B%20%E8%BF%9E%E7%BB%AD%20%2B%20%E7%8B%AC%E7%AB%8B%22%5D%0A%20%20AX%20--%3E%20EU%5B%22U(F)%20%3D%20E_F%20u%22%5D%0A%20%20EU%20--%3E%20AFF%5B%22u%20%E5%9C%A8%E4%BB%BF%E5%B0%84%E5%8F%98%E6%8D%A2%E4%B8%8B%E5%94%AF%E4%B8%80%22%5D%0A%20%20AFF%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%8B%AC%E7%AB%8B%E6%80%A7%E6%98%AF%E5%90%A6%E7%AB%99%E4%BD%8F%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"本课不引入主观概率。状态依存与或有要求权在课序末尾才出现；这里的概率是客观的，彩票是轮盘，不是「哪一个状态会实现」。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[n("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"独立性把跨结果的权衡从分布里拆成逐点的 \\(u\\)，再用概率加总。于是「多一点好结果的概率」可以用 \\(u\\) 的差来标价。保险、资产组合后课会用同一线性结构：随机财富的值等于各结果 \\(u\\) 的平均。没有这一步，风险厌恶只能停留在「不喜欢分散」的口头上。",-1)),(E(),s(l,null,{default:e(()=>[i(r,{id:"mermaid-55",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E8%B5%8C%E5%B1%80%EF%BC%9A%E4%B8%80%E5%8D%8A%E6%A6%82%E7%8E%87%E5%BE%97%20100%20%E4%B8%80%E5%8D%8A%E5%BE%97%200%22%5D%20--%3E%20EM%5B%22%E6%9C%9F%E6%9C%9B%E8%B4%A2%E5%AF%8C%20%3D%2050%22%5D%0A%20%20G%20--%3E%20EU%5B%22%E6%95%88%E7%94%A8%E5%9D%87%E5%80%BC%20%3D%200.5%C2%B7u(100)%20%2B%200.5%C2%B7u(0)%22%5D%0A%20%20EU%20--%3E%20CE%5B%22%E5%8F%8D%E8%A7%A3%E5%87%BA%E7%A1%AE%E5%AE%9A%E6%80%A7%E7%AD%89%E5%80%BC%20CE%22%5D%0A%20%20UCON%5B%22u%20%E6%98%AF%E5%87%B9%E7%9A%84%EF%BC%88%E9%A3%8E%E9%99%A9%E5%8E%8C%E6%81%B6%EF%BC%89%22%5D%20--%3E%20CE%0A%20%20CE%20--%3E%20PREM%5B%22%E9%A3%8E%E9%99%A9%E6%BA%A2%E4%BB%B7%20%3D%20%E6%9C%9F%E6%9C%9B%E8%B4%A2%E5%AF%8C%20-%20CE%20%3E%200%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">数字实例：取 \\(u(x)=\\sqrt{x}\\)。赌局「一半得 100、一半得 0」的效用均值是 \\(0.5\\times 10+0.5\\times 0=5\\)；反解 \\(\\sqrt{CE}=5\\) 得 \\(CE=25\\)。而期望财富是 50——这 25 的差距就是此人愿意花钱买保险的额度。初学者容易以为确定性等值等于期望值，那只在 \\(u\\) 是直线（风险中性）时成立。</span></p><p>线性也带来刀刃：共同的尾事件必须被消掉。若决策者对共同尾事件仍敏感，期望表示失败——这正是阿莱的缺口。本课先把刀磨好，下一课看它切不切得动实验。</p><p><span class="marginnote">有限结果时 \\(u\\) 的值就是 degenerated lottery 的效用。连续结果还要对 \\(u\\) 的有界或积分条件另加技术假设，主干不展开。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>vNM 不处理模糊（概率未知），那是主观期望效用与 Ellsberg，本课序不走。也不处理「对概率非线性加权」的前景理论；主干仍用期望效用，因为后课保险、随机占优、或有要求权都建立在线性期望上。实验偏离是对照。</p><p>确定消费的可积需求与这里的 \\(u\\) 不要焊死。一个人可以在超市满足 GARP，在彩票上违背独立性。两个课序的对象不同。</p><p>Savage 把客观概率换成主观信念，公理更长，本课不走。状态依存课会用客观 \\(\\pi\\) 把彩票改写成或有商品，那是市场对象，不是另一套 vNM。也不要把 \\(\\mathbb{E}u\\) 写成限价簿上的期望盈亏：那里没有伯努利函数，只有报价。</p><p>后课默认：不确定下的工作表示是 \\(\\mathbb{E}u\\)，直到独立性被明确拿掉。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>彩票上的理性加连续仍不够；期望形式来自独立性。</li><li>伯努利 \\(u\\) 在正仿射变换下唯一，这是后课风险厌恶的刻度。</li><li>概率此处是客观的；状态依存另课。</li><li>阿莱将检验独立性，本课不预支结论。</li><li>出处：von Neumann and Morgenstern, <em>Theory of Games and Economic Behavior</em>, 1944；Mas-Colell, Whinston and Green 第 6 章。</li></ul>',10))])}const f=p(u,[["render",B]]);export{F as __pageData,f as default};
